# DC-30
C('D-30', S, 'Design: Internal work order header has an orange outline and the badge',
  ['Sign in as an Admin (a user with every setting, See Financial Data included).', 'Use a desktop browser window 1440 pixels wide at 100% zoom.', 'Have Internal Work Orders turned on in Settings > Work Orders.', 'Have a customer flagged as Internal customer, with one asset, and its default internal category left at General Internal.', 'Have a new internal work order for that customer and asset, with one labor line (1.0 h) and one stock part with a cost (for example $95.00), the line In Progress, made for this test.', 'Open the attached pictures iwo-flow1-08-03-work-order-in-progress.png, iwo-happy-14-14-in-progress-cost-and-hours-no-prices.png, iwo-components-01-wo-detail-artboard-v6.png at 100% zoom beside the screen.'],
  ['Open the internal work order.'],
  [['The "Internal" badge sits next to the status in the header.', 'The header card has an orange outline and a light orange background.', 'The customer card shows no badge and no category, and there is no hint sentence under the header.']],
  ['S2-R3'],
  stories=[2])
# DC-31
C('D-31', S, 'Design: Internal work order lines show cost and hours with no prices',
  ['Sign in as an Admin (a user with every setting, See Financial Data included).', 'Use a desktop browser window 1440 pixels wide at 100% zoom.', 'Have Internal Work Orders turned on in Settings > Work Orders.', 'Have a customer flagged as Internal customer, with one asset, and its default internal category left at General Internal.', 'Have a new internal work order for that customer and asset, with one labor line (1.0 h) and one stock part with a cost (for example $95.00), the line In Progress, made for this test.', 'Open the attached pictures iwo-flow1-08-03-work-order-in-progress.png, iwo-happy-14-14-in-progress-cost-and-hours-no-prices.png at 100% zoom beside the screen.'],
  ['Open the internal work order.'],
  [['The lines table shows quantity, cost and hours, with no Rate, Margin or Total column.', 'There is no total, tax, fee or discount block; in its place one "Shop supplies" field shows a dollar amount.']],
  [('S2-R4', "Lines on an internal or no-charge work order show quantity, cost (parts) and hours (labor) and no sell prices: the Rate, Margin and Total columns of the lines table (a part's sell price sits in Rate) and the Sell price, Rate and Margin fields of the line and part dialogs are hidden and not required; there is no work order total, tax, fee or discount block; the shop supplies block is the flat amount of Story 10."), ('S10-R1', 'An internal or no-charge work order carries one field "Shop supplies" (a dollar amount) in the block where a billable work order shows its totals.')],
  stories=[2, 10])
# DC-32
C('D-32', S, 'Design: Internal work order three-dots menu has no invoice or deposit items',
  ['Sign in as an Admin (a user with every setting, See Financial Data included).', 'Use a desktop browser window 1440 pixels wide at 100% zoom.', 'Have Internal Work Orders turned on in Settings > Work Orders.', 'Have a customer flagged as Internal customer, with one asset, and its default internal category left at General Internal.', 'Have a new internal work order for that customer and asset, with one labor line (1.0 h) and one stock part with a cost (for example $95.00), the line In Progress, made for this test.', 'Make sure the organization does not require review before completion.', 'Open the attached picture iwo-flow1-09-3c-menu-internal.png at 100% zoom beside the screen.'],
  ['Open the internal work order.', 'Click the three-dots menu in the header.'],
  [['The work order opens with the line In Progress.'], ['The menu holds "Close Work Order" where Create invoice would be.', 'It has no "Send to Portal", "Request IBS Approval", "Add Deposit" or "Add Work Order Fee / Discount".']],
  [('S3-N2', 'With review off and open lines, Close Work Order sits in the three-dots menu exactly as Create invoice does today; once every line is Complete it is the header button and leaves the menu, as Create invoice does.'), ('S2-R11', 'On an internal work order "Send to Portal" and "Request IBS Approval" are not shown.'), 'S2-N5', ('S2-R15', 'When a work order becomes internal or no charge, its work order fees and discounts and its line discounts are removed with the prices, and "Add Work Order Fee / Discount" is not shown in its menu.')],
  stories=[2, 3])
